sample.code:
# Open the WebSocket chat stream
wscat -c wss://chat.kale.ardictech.com/ws   -H "Authorization: Bearer $JWT"
# Server hello: {"type":"hello","session":"..."}
# Send a user message:
{"type":"msg","text":"OEE for line 3?"}

import requests
r = requests.post(
    "http://fastapi:8000/api/chat",
    headers={"Authorization": f"Bearer {jwt}"},
    json={"tenant_id":"kale","message":"OEE for line 3?"}
)
# → 200 {"reply":"Line 3 OEE today: 87%...","trace_id":"..."}

# Evaluate a tenant access policy
curl -X POST http://opa:8181/v1/data/authz/allow   -H "Content-Type: application/json"   -d '{"input":{"user":{"tenant":"kale","roles":["operator"]},"action":"read","resource":"oee"}}'
# → {"result":true}

# Provision a new tenant end-to-end
curl -X POST http://tenant-prov:8000/provision   -H "Authorization: Bearer $ADMIN_JWT"   -d '{"tenant_id":"kale-seramik","plan":"enterprise","admin_email":"admin@kale.com.tr"}'
# → 202 {"job_id":"...","status":"queued"}

import requests
r = requests.post("http://langgraph:8001/invoke", json={
    "agent": "galip_usta",
    "tenant_id": "kale-seramik",
    "session_id": "abc123",
    "messages": [{"role":"user","content":"OEE for line 3?"}]
})
# → {"output":"Line 3 OEE today is 87%...","trace_id":"langfuse-..."}

from decision_engine import Engine
eng = Engine.load("/app/rules/insurance/")
result = eng.decide(
    candidates=[{"name":"approve","score":0.82},{"name":"refer","score":0.71}],
    context={"premium":50000,"history":"clean"}
)
# → {"decision":"approve","rule_id":"low_risk_clean","trace":[...]}

# Fetch the active version of a prompt template
curl http://prompt-store:8000/admin/prompts/galip_usta_oee_query?lang=tr
# → {"id":"galip_usta_oee_query","version":"v3","lang":"tr","template":"..."}

# Fetch current session memory (LangGraph injects this every turn)
curl http://memori:8000/session/abc123   -H "X-Tenant-Id: kale-seramik"
# → {"history":[...],"summary":"User asked about line 3 OEE; concerned about Tuesday dip."}

# Generate an IATF 16949 audit PDF
curl -X POST http://audit-pdf:8000/generate   -H "Authorization: Bearer $JWT"   -d '{"tenant":"kale","period":"2026-Q2","standard":"IATF-16949"}'
# → {"job_id":"...","url":"https://minio/audit-pdfs/kale/2026-q2.pdf?...(24h-expiry)"}

# Upload a catalog file; triggers RAG re-indexing
curl -X POST http://file-upload:8000/upload   -H "Authorization: Bearer $JWT"   -F "file=@catalog.csv"   -F "tenant=kale"   -F "purpose=rag_indexing"
# → {"sha256":"...","triggered_dag":"rag_reindex","run_id":"..."}

# Trigger a sync manually
curl -X POST http://airbyte:8001/api/v1/connections/sync   -H "Content-Type: application/json"   -d '{"connectionId":"$CONNECTION_ID"}'
# → 200 {"job":{"id":...,"status":"running","createdAt":...}}
